        path.join(tempDir, 'kynetic.meta.yaml'),
        yamlStringify(metaManifest),
      );

      const meta = await loadMetaContext(ctx);
      const found = findMetaItemByRef(meta, 'nonexistent');
      expect(found).toBeUndefined();
    });
  });

